function nav(){const iconNames={home:'house',knowledge:'journal-bookmark',quran:'book',adhkar:'circle',more:'person'};const activeRoute=['learning','umrah'].includes(currentRoute)?'knowledge':['account','admin','staff','support','settings','about','sources','day','prayer','history','calendar','support-salah'].includes(currentRoute)?'more':currentRoute;for(const id of ['desktop-nav','mobile-nav']){const target=document.getElementById(id);target.setAttribute('data-i18n-aria-label','nav.label');target.setAttribute('aria-label',t('nav.label'));target.innerHTML=routes.map(([key,name])=>'<a class="nav-item '+(activeRoute===key?'active':'')+'" '+(activeRoute===key?'aria-current="page"':'')+' href="#'+key+'"><span class="nav-symbol" aria-hidden="true"><img src="./assets/'+iconNames[key]+'.svg" alt=""></span><span data-i18n="'+name+'">'+esc(t(name))+'</span></a>').join('');}const locationButton=document.getElementById('location-button');locationButton.textContent=settings.city?settings.city.name:t('home.chooseCity');if(settings.city)locationButton.removeAttribute('data-i18n');else locationButton.setAttribute('data-i18n','home.chooseCity');}
const hijriMonthKeys=['One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve'];
function publicDateMarkup(value,{zone='UTC',style='long'}={}){return '<span data-public-date="'+esc(value)+'" data-public-zone="'+esc(zone||'')+'" data-public-date-style="'+style+'">'+esc(publicDateText(value,zone,style))+'</span>'}
function publicDateText(value,zone,style){return new Intl.DateTimeFormat(getLocale(),{...(zone?{timeZone:zone}:{}),...(style==='short'?{dateStyle:'short',timeStyle:'short',hourCycle:'h23'}:{day:'numeric',month:'long',year:'numeric'})}).format(new Date(value))}
function publicHijriMarkup(day,month,year){const key=hijriMonthKeys[month-1];if(!key)return '';return '<span data-public-hijri-day="'+esc(day)+'" data-public-hijri-month="'+month+'" data-public-hijri-year="'+esc(year)+'">'+esc(t('hijriUi.date',{day,month:t('hijriUi.month'+key),year}))+'</span>'}
function publicPrayerAttribute(key,nameKey,attribute='aria-label'){return uiAttribute(key,{name:t(nameKey)},attribute)+' data-public-prayer-'+attribute+'="'+key+'" data-public-prayer-name="'+nameKey+'"'}
function updatePublicUi(){for(const node of document.querySelectorAll('[data-public-date]'))node.textContent=publicDateText(node.dataset.publicDate,node.dataset.publicZone,node.dataset.publicDateStyle);for(const node of document.querySelectorAll('[data-public-hijri-day]')){const month=hijriMonthKeys[Number(node.dataset.publicHijriMonth)-1];if(month)node.textContent=t('hijriUi.date',{day:node.dataset.publicHijriDay,month:t('hijriUi.month'+month),year:node.dataset.publicHijriYear})}for(const node of document.querySelectorAll('[data-public-prayer-name]'))for(const attribute of ['aria-label','title']){const key=node.getAttribute('data-public-prayer-'+attribute);if(key)setUiAttribute(node,attribute,key,{name:t(node.dataset.publicPrayerName)})}for(const node of document.querySelectorAll('[data-public-weather-code]'))node.textContent=weatherName(Number(node.dataset.publicWeatherCode));const status=document.getElementById('weather-status');if(status)status.textContent=weatherLabel()}
subscribeLanguage(updatePublicUi);
function dateHeader(){const h=days[currentDay]?.hijri;return '<div class="date"><strong>'+ (h?publicHijriMarkup(h.day,h.month.number,h.year):'')+'</strong>'+publicDateMarkup(new Date().toISOString(),{zone:settings.city?.timezone||''})+'</div>'}
function schedule(){const times=timingsFor(currentDay,days),next=nextPrayer(Date.now(),currentDay,days);return '<div class="panel-head"><h2>'+uiLeaf('journalUi.todayPrayers')+'</h2><a class="text-button" href="#calendar">'+uiLeaf('menu.calendar')+'</a></div>'+prayers.map(([key])=>{const nameKey='home.'+key.toLowerCase();return '<div class="prayer-row '+(next?.key===key?'next':'')+'"><span class="name">'+uiLeaf(nameKey)+'</span><button class="schedule-time" data-time-toggle '+uiAttribute('journalUi.largeCountdown')+'><time>'+ (times?formatTime(times[key]):'—')+'</time></button><button class="mark '+(history[currentDay]?.[key]?'done':'')+'" data-mark="'+key+'" '+publicPrayerAttribute(history[currentDay]?.[key]?'journalUi.changeMark':'journalUi.addMark',nameKey)+'>'+(history[currentDay]?.[key]?'✓':'○')+'</button></div>'}).join('')+'<div class="sunrise"><span>'+uiLeaf('journalUi.sunriseNote')+'</span><time>'+(times?formatTime(times.Sunrise):'—')+'</time></div>'}
function dayPanel(){const count=prayers.filter(([k])=>history[currentDay]?.[k]).length;return '<section class="panel day"><div class="panel-head"><h2>'+uiLeaf('journalUi.today')+'</h2><span class="muted">'+uiLeaf('journalUi.todayMarks',{count})+'</span></div><div class="day-dots">'+prayers.map(([k])=>{const nameKey='home.'+k.toLowerCase();return '<div class="day-dot"><button class="day-mark '+(history[currentDay]?.[k]?'done':'')+'" data-day-mark="'+k+'" aria-pressed="'+Boolean(history[currentDay]?.[k])+'" '+publicPrayerAttribute(history[currentDay]?.[k]?'journalUi.doneLabel':'journalUi.unmarkedLabel',nameKey)+'>'+(history[currentDay]?.[k]?'✓':'○')+'</button>'+uiLeaf(nameKey)+'</div>'}).join('')+'</div><div class="progress"><span style="width:'+count*20+'%"></span></div><p class="muted" style="margin:17px 0 0">'+uiLeaf('journalUi.privateMarks')+'</p></section>'}
function hero(){const next=nextPrayer(Date.now(),currentDay,days);return '<section class="hero"><button class="time-toggle" data-time-toggle aria-expanded="'+(prayerDisplay==='focus')+'" '+uiAttribute(prayerDisplay==='focus'?'home.showDaySchedule':'journalUi.largeCountdown')+'><span class="eyebrow">'+uiLeaf('journalUi.nextPrayer')+'</span><span class="next-prayer-name" id="next-name">'+uiLeaf(next?'home.'+next.key.toLowerCase():settings.city?'home.schedule':'journalUi.yourCity')+'</span><span class="prayer-time" id="next-time">'+(next?formatTime(next.time):'—')+'</span><span class="countdown" id="countdown">'+(next?countdown(next.time-Date.now()):'— : — : —')+'</span><span class="hero-note" id="next-note">'+(next?'':uiLeaf(loading?'journalUi.loadingChecked':settings.city?'journalUi.unavailable':'journalUi.chooseCity'))+'</span><span class="toggle-hint">'+uiLeaf(prayerDisplay==='focus'?'journalUi.openScheduleHint':'journalUi.openCountdownHint')+'</span></button><div class="hero-bottom"><button class="weather-button" id="weather-status">'+esc(weatherLabel())+'</button><a href="#qibla" class="chip">◎ '+uiLeaf('menu.qibla')+'</a></div></section>'}
function weatherLabel(){if(!settings.weather)return t('weatherUi.off');if(weatherFrame(weather,Date.now()).fresh)return Math.round(weather.temperature_2m)+'° · '+weatherName(weather.weather_code);return t(weatherBusy?'weatherUi.refreshing':weather?'weatherUi.stale':'weatherUi.noFresh')}

function tahajjudEntry(now=Date.now(),chosenTime=''){const value=tahajjudFor(now,{previous:timingsFor(addDays(currentDay,-1),days),today:timingsFor(currentDay,days),next:timingsFor(addDays(currentDay,1),days)},chosenTime);return value?{...value,text:value.kind==='manual'?value.text:formatTime(value.time)}:null}
async function ensureTahajjudDays(){const id=refreshId,day=currentDay,previousDay=addDays(day,-1);if(!(settings.showTahajjud||settings.reminders?.tahajjud?.enabled)||!settings.city||days[previousDay])return;try{const fetched=await loadMonth(previousDay);if(id===refreshId&&day===currentDay)days={...days,...fetched}}catch{/* An absent adjacent date stays unavailable. */}}
function centralSurface(){const now=Date.now(),times=timingsFor(currentDay,days),next=homeEvent(now,nextPrayer(now,currentDay,days),times?.Sunrise,currentDay);return PrayerDisplay({mode:prayerDisplay,next,times,loading,hasCity:!!settings.city,asr:asrInfo(currentDay,days),nextAsr:next?asrInfo(next.day,days):null,tahajjud:settings.showTahajjud?{shown:true,...tahajjudEntry(now)}:null})}
function home(){void preloadLearningCabinetLink(counterSyncStatus().signedIn?counterSyncStatus().userId:null);app.innerHTML='<div class="app-home-shell"><span id="home-radio-entry" class="home-radio-entry" hidden></span><span id="home-listening-now" class="home-listening-now" data-i18n-title="home.nowInSalah" title="'+esc(t('home.nowInSalah'))+'" hidden></span><div class="home-prayer-center"><div class="app-home-top"><div class="app-home-brand">SALAH</div><div id="home-location-controls" class="home-location-controls"></div></div>'+travelHomeMarkup()+centralSurface()+'<div id="home-owner-update" hidden></div>'+(error?'<p class="error" role="status"'+(errorKey?' data-i18n="'+errorKey+'"':'')+'>'+esc(errorKey?t(errorKey):error)+'</p>':'')+(prayerDisplay==='timetable'?'<div id="home-adhkar-suggestion"></div><div id="home-notification-invite"></div>':'')+'</div></div>';stopHomeRadioEntry?.();stopHomeRadioEntry=mountHomeRadioEntry(document.getElementById('home-radio-entry'));homeListeningNow.mount(document.getElementById('home-listening-now'));document.getElementById('home-location-controls').append(locationControl);notificationInvite.mount(document.getElementById('home-notification-invite'));ownerReleaseCard.mount(document.getElementById('home-owner-update'));bindMarks();bindTravelHome(app,travelHooks);bindQiblaSwipe(app.querySelector('.central-prayer.timetable'),()=>{prepareQiblaAccess();location.hash='qibla'})}
