function exportData(){let backup;try{backup=createBackup({storage:localStorage,settings,history})}catch{toast(t('backupUi.exportReadFailed'));return}const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='salah-backup-'+currentDay+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(backup.warnings?.length?t('backupUi.exportSkipped'):t('backupUi.exportReady'))}
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});async function installApp(){if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast(t('settingsExtra.installHint'))}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_prayer_schedule',description:'Прочитать доступное расписание и следующую молитву для выбранного города.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({city:settings.city?.name||null,date:currentDay,next:nextPrayer(Date.now(),currentDay,days),times:timingsFor(currentDay,days),method:methods[settings.method]})});register({name:'set_prayer_mark',description:'Сохранить личную отметку сегодняшней молитвы или убрать её.',inputSchema:{type:'object',properties:{prayer:{type:'string',enum:prayers.map(p=>p[0])},status:{type:'string',enum:['ontime','later','clear']}},required:['prayer','status'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!prayers.some(p=>p[0]===input.prayer)||!['ontime','later','clear'].includes(input.status))throw Error('Недопустимая молитва или статус');if(!markPrayer(currentDay,input.prayer,input.status==='clear'?null:input.status))throw Error('Хранилище недоступно');render();return{date:currentDay,prayer:input.prayer,status:history[currentDay][input.prayer]}}})}

function weatherDialog(){if(!settings.weather){location.hash='settings';return}const fresh=weatherFrame(weather,Date.now()).fresh;modal('<div class="modal-head"><h2>'+uiLeaf('weatherUi.title')+'</h2><button class="icon-button" data-close '+uiAttribute('common.close')+'>×</button></div><h3>'+esc(settings.city?.name||'')+'</h3>'+(fresh?'<p class="muted"><span data-public-weather-code="'+weather.weather_code+'">'+esc(weatherName(weather.weather_code))+'</span><br>'+uiLeaf('weatherUi.temperature',{value:Math.round(weather.temperature_2m)})+'<br>'+uiLeaf('weatherUi.feelsLike',{value:Math.round(weather.apparent_temperature)})+(Number.isFinite(weather.wind_speed_10m)?'<br>'+uiLeaf('weatherUi.wind',{value:Math.round(weather.wind_speed_10m)}):'')+'<br>'+uiLeaf('weatherUi.dataOn')+' '+publicDateMarkup(new Date(weather.dataAt).toISOString(),{zone:settings.city?.timezone,style:'short'})+'</p>':'<p class="muted">'+uiLeaf('weatherUi.unavailable')+' '+(weather?uiLeaf('weatherUi.savedStale'):'')+uiLeaf('weatherUi.timeOfDay')+'</p>')+'<a class="text-button source-reference" href="https://open-meteo.com/" target="_blank" rel="noopener">'+uiLeaf('weatherUi.source')+'</a><button type="button" class="button secondary" id="weather-refresh" style="margin-top:16px">'+uiLeaf('weatherUi.refresh')+'</button><p class="muted" role="status" id="weather-refresh-result"></p>');const button=document.getElementById('weather-refresh');button.disabled=weatherBusy;button.onclick=async()=>{button.disabled=true;setUiMessage(button,uiMessage('weatherUi.refreshing'));if(await refreshWeather(true)){if(button.isConnected&&document.getElementById('modal').open&&document.getElementById('weather-refresh')===button)weatherDialog()}else if(button.isConnected&&document.getElementById('modal').open){button.disabled=false;setUiMessage(button,uiMessage('weatherUi.refresh'));setUiMessage(document.getElementById('weather-refresh-result'),uiMessage('weatherUi.refreshFailed'))}}}
async function importData(event){
 const input=event.target,file=input.files?.[0];input.value='';if(!file)return;
 if(file.size>5*1024*1024){toast(t('backupUi.importSize'));return}
 let prepared;try{prepared=validateBackup(await file.text())}catch(error){toast(error.message||t('backupUi.readFailed'));return}
 const p=prepared.preview;
 modal('<div class="modal-head"><h2 data-i18n="backupUi.restoreTitle">'+esc(t('backupUi.restoreTitle'))+'</h2><button class="icon-button" data-close data-i18n="common.close" data-i18n-aria-label="common.close" aria-label="'+esc(t('common.close'))+'">'+esc(t('common.close'))+'</button></div><p class="muted" data-i18n="backupUi.restoreNote">'+esc(t('backupUi.restoreNote'))+'</p><div class="backup-preview"><p><span data-i18n="backupUi.city">'+esc(t('backupUi.city'))+'</span> <span'+(p.city?'':' data-i18n="backupUi.noCity"')+'>'+esc(p.city||t('backupUi.noCity'))+'</span></p><p data-backup-count="days"></p><p data-backup-count="bookmarks"></p><p data-backup-count="repetitions"></p></div>'+(prepared.warnings.length?'<p class="muted">'+prepared.warnings.map(esc).join('<br>')+'</p>':'')+'<div class="button-row"><button type="button" class="button secondary" id="backup-current" data-i18n="backupUi.saveCurrent">'+esc(t('backupUi.saveCurrent'))+'</button><button type="button" class="button" id="restore-backup" data-i18n="backupUi.restore">'+esc(t('backupUi.restore'))+'</button></div>');
 const preview=document.querySelector('.backup-preview'),paintPreview=()=>{const format=n=>Number(n).toLocaleString(getLocale()),rows=[['days','backupUi.daysAndMarks',{days:format(p.days),marks:format(p.prayerMarks)}],['bookmarks','backupUi.bookmarks',{count:format(p.bookmarks)}],['repetitions','backupUi.repetitions',{count:format(p.adhkarRepetitions)}]];for(const[id,key,params]of rows){const node=preview.querySelector('[data-backup-count="'+id+'"]');node.setAttribute('data-i18n',key);node.setAttribute('data-i18n-params',JSON.stringify(params));node.textContent=t(key,params);}};paintPreview();const offPreview=subscribeLanguage(paintPreview);document.getElementById('modal').addEventListener('close',offPreview,{once:true});
 document.getElementById('backup-current').onclick=exportData;
 document.getElementById('restore-backup').onclick=()=>{try{restoreBackup(prepared,{storage:localStorage,confirmed:true});closeModal();reminders.reset();stopCompass();stopLearning();stopAdhkar();stopQuran();quranRenderedHash=null;calendarRequestId++;days={};weatherRequestId++;weatherBusy=false;weather=null;lastWeatherCheck=0;currentDay=dateKey();location.hash='settings';refresh(false,false);toast(t('backupUi.restored'))}catch(error){toast(error.message||t('backupUi.restoreError'))}};
}

let calendarPdfBusy=false;
async function downloadCalendarMonth(format='pdf'){
 if(calendarPdfBusy||!settings.city)return;
 const buttons=[document.getElementById('calendar-download'),document.getElementById('calendar-image')],button=buttons[format==='pdf'?0:1],month=(calendarStart||currentDay).slice(0,7),city={...settings.city};
 const context=()=>JSON.stringify([settings.city,settings.method,settings.school,settings.highLatitude,settings.tyumenTimeSource,settings.offsets,settings.tableOffsets]);
 const snapshot=context(),school=Number(settings.school);calendarPdfBusy=true;buttons.forEach(b=>{if(b)b.disabled=true});if(button)setUiMessage(button,uiMessage('calendarUi.preparing'))
 try{
  const [firstDays,hanafiDays]=await Promise.all([loadMonth(month+'-01',false,0),loadMonth(month+'-01',false,1)]);
  if(context()!==snapshot||currentRoute!=='calendar')return;
  const fullDays={...days,...(school===1?hanafiDays:firstDays)},rows=monthRows(month,day=>{const first=timingsFor(day,firstDays,0),hanafi=timingsFor(day,hanafiDays,1);return first&&hanafi?{...timingsFor(day,fullDays,school),AsrFirst:first.Asr,AsrHanafi:hanafi.Asr}:null},time=>formatTime(time,city.timezone));
  const source=usesAlHakk()?tyumenSource(month+'-01',fullDays).label:methods[settings.method];
  const file=await createMonthFile({month,city:city.name,rows,source,localAsr:usesAlHakk()},format);
  if(context()!==snapshot||currentRoute!=='calendar')return;
  const fileUrl=URL.createObjectURL(file),name='SALAH-'+month+'-A4.'+format;
  modal('<div class="modal-head"><h2>'+uiLeaf('calendarUi.monthTitle')+'</h2><button class="icon-button" data-close '+uiAttribute('common.close')+'>×</button></div>'+(format==='png'?'<img class="calendar-export-preview" src="'+fileUrl+'" '+uiAttribute('calendarUi.previewAlt',{},'alt')+'>':'<p class="muted">'+uiLeaf('calendarUi.a4Note')+'</p>')+'<a class="button" href="'+fileUrl+'" download="'+name+'">'+uiLeaf(format==='pdf'?'calendarUi.downloadPdf':'calendarUi.downloadImage')+'</a>');
  setTimeout(()=>URL.revokeObjectURL(fileUrl),300000);
 }catch(error){toast(error.uiMessage||error.message||uiMessage('calendarUi.prepareFailed'))}
 finally{calendarPdfBusy=false;buttons.forEach((b,i)=>{if(b){b.disabled=false;setUiMessage(b,uiMessage(i===0?'calendarUi.pdfA4':'calendarUi.image'))}})}
}

